import {createRegistry} from './set-registry.mjs?v=sets-2';
import {mountLibrary} from './library.mjs?v=sets-2';
import {mountMap} from './map.mjs?v=sets-2';
import {matchTags,findTrio,deal,advance,setActiveSets} from './engine.mjs?v=sets-2';
const $=id=>document.getElementById(id),KEY='nowadays-visual-game-v4',LIB_KEY='nowadays-set-library-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mapGame=null,atlas=null,registry=null;
let cards=[],tags={},byId=new Map(),board=[],remaining=[],selected=[],found=[],pending=null,hinted=[],hintStep=0,playable=true;
const chips=list=>list.map(t=>`<span class="chip" title="${esc(tags[t].zh)}">${esc(tags[t].en)}</span>`).join('');
function msg(text,kind=''){$('status').textContent=text;$('status').className=kind;}
const success=()=>`+1 set · ${pending.tags.length} connection${pending.tags.length===1?'':'s'}`;
function save(){try{localStorage.setItem(KEY,JSON.stringify({board:board.map(c=>c.id),remaining:remaining.map(c=>c.id),found,pending}));}catch{}}
function restore(){try{const s=JSON.parse(localStorage.getItem(KEY));if(!s||!Array.isArray(s.board)||!Array.isArray(s.remaining)||!Array.isArray(s.found))return false;const pendingIds=s.pending?.ids||[],claimed=s.found.flatMap(f=>f.ids),partition=[...s.board,...s.remaining,...claimed.filter(id=>!pendingIds.includes(id))];if(partition.length!==cards.length||new Set(partition).size!==cards.length||partition.some(id=>!byId.has(id))||s.board.length>12)return false;for(const f of s.found)if(!matchTags(f.ids.map(id=>byId.get(id))).length)return false;if(s.pending&&(!s.pending.ids.every(id=>s.board.includes(id))||!matchTags(s.pending.ids.map(id=>byId.get(id))).length))return false;board=s.board.map(id=>byId.get(id));remaining=s.remaining.map(id=>byId.get(id));found=s.found.map(f=>({...f,tags:matchTags(f.ids.map(id=>byId.get(id)))}));pending=s.pending?{...s.pending,tags:matchTags(s.pending.ids.map(id=>byId.get(id)))}:null;selected=pending?[...pending.ids]:[];playable=!!findTrio([...board,...remaining]);return true;}catch{return false;}}
function renderBoard(){
 $('score').textContent=found.length;$('score-unit').textContent=found.length===1?'set':'sets';$('found-count').textContent=found.length;$('deck-meta').textContent=`${remaining.length} left`;
 $('board').innerHTML=board.map((c,i)=>`<div class="card-wrap"><button class="card ${selected.includes(c.id)?'selected':''} ${hinted.includes(c.id)?'hint':''} ${pending?.ids.includes(c.id)?'good':''}" data-card="${c.id}" aria-pressed="${selected.includes(c.id)}" aria-label="Card ${i+1}: ${esc(c.title)}" ${pending?'disabled':''}><img src="${c.image}" alt="${esc(c.title)}" draggable="false"><span class="slot">${String(i+1).padStart(2,'0')}</span>${selected.includes(c.id)?`<span class="selected-mark">${selected.indexOf(c.id)+1}</span>`:''}</button><button class="zoom" data-zoom="${c.id}" aria-label="Enlarge ${esc(c.title)}">⤢</button></div>`).join('');
 $('selected-count').textContent=`${selected.length} / 3`;$('check').disabled=!pending&&(selected.length!==3||!playable);$('check').innerHTML=pending?'Next <span>↗</span>':'Check <span>↗</span>';$('clear').disabled=!!pending||!selected.length;$('redeal').disabled=!!pending||!playable;$('hint').disabled=!!pending||!playable;$('match-tags').innerHTML=pending?chips(pending.tags):'';renderFound();
}
function start(preferred=[]){({board,remaining,playable}=deal(cards,Math.random,Array.isArray(preferred)?preferred:[]));selected=[];found=[];pending=null;hinted=[];hintStep=0;renderBoard();msg(playable?'':'No sets in Library. Add one to play.');save();}
function select(id){if(pending||!playable)return;hinted=[];hintStep=0;if(selected.includes(id))selected=selected.filter(x=>x!==id);else if(selected.length<3)selected.push(id);else{msg('Check or swap a card.');return;}renderBoard();msg('');}
function check(){if(pending){next();return;}if(selected.length!==3)return;const links=matchTags(selected.map(id=>byId.get(id)));if(!links.length){document.querySelectorAll('.card.selected').forEach(b=>b.classList.add('bad'));msg('Try another trio.','error');return;}pending={ids:[...selected],tags:links};found.push({...pending});hinted=[];hintStep=0;renderBoard();msg(success(),'success');save();}
function next(){const n=advance(board,remaining,pending.ids.map(id=>byId.get(id)));({board,remaining,playable}=n);pending=null;selected=[];hinted=[];hintStep=0;renderBoard();msg(!playable?'Round complete.':n.reshuffled?'Reshuffled.':'');save();}
function redeal(){if(pending)return;({board,remaining,playable}=deal([...board,...remaining]));selected=[];hinted=[];hintStep=0;renderBoard();msg(playable?'':'Round complete.');save();}
function showView(view){for(const [name,section,tab] of [['play','game-view','play-tab'],['map','map-view','map-tab'],['library','library-view','library-tab']]){const active=name===view;$(section).hidden=!active;$(tab).classList.toggle('active',active);$(tab).setAttribute('aria-pressed',active);}if(view==='library')atlas?.show();if(view==='map')mapGame?.show();}
function detail(id){atlas?.detail(id);}
function renderFound(){$('found-list').innerHTML=found.length?found.map((f,i)=>`<article class="found-set"><small>SET ${String(i+1).padStart(2,'0')}</small><div class="found-images">${f.ids.map(id=>`<img src="${byId.get(id).image}" alt="${esc(byId.get(id).title)}">`).join('')}</div><div class="chips">${chips(f.tags)}</div></article>`).join(''):'<p class="muted">No sets yet.</p>';}
async function init(){try{const response=await fetch('./data.json?v=sets-2');if(!response.ok)throw new Error('Image collection unavailable');({cards,tags}=await response.json());byId=new Map(cards.map(c=>[c.id,c]));tags.custom={en:'Your set',zh:'自定义组合'};let savedLibrary;try{savedLibrary=JSON.parse(localStorage.getItem(LIB_KEY));}catch{}registry=createRegistry(cards,savedLibrary);setActiveSets(registry.all());mapGame=mountMap(cards);atlas=mountLibrary(cards,tags,registry,ids=>{setActiveSets(registry.all());try{localStorage.setItem(LIB_KEY,JSON.stringify(registry.snapshot()));}catch{start(ids);return false;}start(ids);return true;});if(restore()){renderBoard();msg(pending?success():playable?'':'Round complete.',pending?'success':'');}else start();
 $('board').addEventListener('click',e=>{const z=e.target.closest('[data-zoom]'),c=e.target.closest('[data-card]');if(z)detail(+z.dataset.zoom);else if(c)select(+c.dataset.card);});$('check').onclick=check;$('clear').onclick=()=>{selected=[];hinted=[];hintStep=0;renderBoard();msg('');};
 $('hint').onclick=()=>{const h=findTrio(board);if(!h){redeal();return;}selected=[];hintStep=Math.min(3,hintStep+1);hinted=h.cards.slice(0,hintStep).map(c=>c.id);renderBoard();msg(`${tags[h.tag].en} · ${hintStep} / 3`);};$('redeal').onclick=redeal;$('restart').onclick=start;
 for(const [tab,view] of [['play-tab','play'],['map-tab','map'],['library-tab','library']])$(tab).onclick=()=>{location.hash=view;showView(view);};const route=()=>showView(['map','library'].includes(location.hash.slice(1))?location.hash.slice(1):'play');window.addEventListener('hashchange',route);route(); document.querySelectorAll('.dialog-close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));$('collection-open').onclick=()=>{$('found-section').hidden=false;$('found-section').scrollIntoView({behavior:'smooth',block:'start'});};$('collection-close').onclick=()=>{$('found-section').hidden=true;};
 }catch(error){msg('Could not load. Please refresh.','error');console.error(error);}}
init();
